pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract RevertingCounterparty {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("always revert");
    }
}

contract InvMutTest is Test {
    airPort c;

    function setUp() public {
        c = new airPort();
    }

    function testFuzz_property(address from, address to, uint256 v) public {
        vm.assume(from != address(0) || to != address(0));
        RevertingCounterparty callee = new RevertingCounterparty();
        address[] memory tos = new address[](1);
        tos[0] = to == address(callee) ? address(0xdead) : to;

        bool ok = true;
        try c.transfer(from, address(callee), tos, v) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
